edits.after:
onClick (event) {
  const closeTarget = event.target.closest(`[${this.config.closeTrigger}]`)
  if (closeTarget && event.target === closeTarget) {
    event.preventDefault()
    event.stopPropagation()
    this.closeModal(event)
  }
}

